tool_input.command:
databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "CREATE OR REPLACE TABLE workspace.mlpab1a346b.scored288ecf (request_id STRING NOT NULL, account_id STRING, distance_deg DOUBLE, score DOUBLE, CONSTRAINT scored288ecf_pk PRIMARY KEY (request_id)) TBLPROPERTIES (delta.enableChangeDataFeed = true)"
}'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "INSERT INTO workspace.mlpab1a346b.scored288ecf SELECT r.request_id, r.account_id, ROUND(SQRT(POW(r.request_lat - p.home_lat, 2) + POW(r.request_lon - p.home_lon, 2)), 6) AS distance_deg, ROUND(p.base_score - 0.1 * ROUND(SQRT(POW(r.request_lat - p.home_lat, 2) + POW(r.request_lon - p.home_lon, 2)), 6), 6) AS score FROM read_files(\"/Volumes/workspace/mlpab1a346b/raw/requests.csv\", format => \"csv\", header => true) r JOIN read_files(\"/Volumes/workspace/mlpab1a346b/raw/profiles.csv\", format => \"csv\", header => true) p ON r.account_id = p.account_id"
}'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "SELECT * FROM workspace.mlpab1a346b.scored288ecf ORDER BY request_id LIMIT 3"
}' | grep -A20 data_array

databricks database create-synced-database-table workspace.mlpab1a346b.scored288ecf_online --json '{
  "database_instance_name": "mlpab1a346b-online-store",
  "spec": {
    "source_table_full_name": "workspace.mlpab1a346b.scored288ecf",
    "primary_key_columns": ["request_id"],
    "scheduling_policy": "SNAPSHOT",
    "create_database_objects_if_missing": true
  }
}' 2>&1 | head -30
